// Long-term nurture: pick contacts due for their next value/seasonal touch.
// AI writes the copy downstream; this node selects who's due + builds the content brief.
// Version-safe Luxon/Date math (no $DateTime). Business-hours + daily-cap + frequency-cap gated.
const openH = Number($env.BUSINESS_HOURS_START || 9);
const closeH = Number($env.BUSINESS_HOURS_END || 18);
if (!($now.hour >= openH && $now.hour < closeH)) return []; // quiet/business-hours gate
const interval = Number($env.NURTURE_INTERVAL_DAYS || 30);
const freqCap = Number($env.FREQUENCY_CAP_DAYS || Math.max(7, Math.floor(interval / 2)));
const maxTouches = Number($env.MAX_TOUCHES || 0); // 0 = evergreen (never stop)
const channelsRaw = (($env.NURTURE_CHANNELS || 'email,sms').split(',')).map(s => s.trim().toLowerCase()).filter(Boolean);
const dailyCap = Number($env.DAILY_CAP || 200);
const biz = $env.BUSINESS_NAME || 'us';
const industry = $env.BUSINESS_INDUSTRY || 'local service';
const nowMs = $now.toMillis();
const today = $now.toISODate();
const month = $now.monthLong;
const seasons = ['Winter','Winter','Spring','Spring','Spring','Summer','Summer','Summer','Fall','Fall','Fall','Winter'];
const season = seasons[$now.month - 1];
const yes = v => String(v || '').toLowerCase() === 'yes';
const dateOf = v => { const t = new Date(v).getTime(); return isNaN(t) ? '' : new Date(t).toISOString().slice(0,10); };
const rows = $input.all().map(i => i.json);
const sentToday = rows.filter(r => r.Last_Touch_At && dateOf(r.Last_Touch_At) === today).length;
let remaining = Math.max(0, dailyCap - sentToday);
const terminal = s => ['unsubscribed','do not contact','converted','bounced','complete'].some(t => s.includes(t));
const out = [];
for (const r of rows) {
  if (remaining <= 0) break;
  if (yes(r.Opted_Out)) continue;
  if (String(r.Sequence_Active || 'Yes').toLowerCase() !== 'yes') continue;
  if (terminal(String(r.Status || '').toLowerCase())) continue;
  if (!r.Customer_Phone && !r.Customer_Email) continue;
  const count = Number(r.Touch_Count || 0);
  if (maxTouches > 0 && count >= maxTouches) continue;
  // Frequency cap: never message the same contact more often than freqCap days.
  if (r.Last_Touch_At && (nowMs - new Date(r.Last_Touch_At).getTime()) < freqCap * 86400000) continue;
  const due = r.Next_Touch_At ? nowMs >= new Date(r.Next_Touch_At).getTime() : true;
  if (!due) continue;
  const nextCount = count + 1;
  const isLast = maxTouches > 0 && nextCount >= maxTouches;
  // Channel rotation by touch index, falling back to whatever the contact actually has.
  let channel = channelsRaw[count % channelsRaw.length] || 'email';
  if (channel === 'email' && !r.Customer_Email) channel = 'sms';
  if (channel === 'sms' && !r.Customer_Phone) channel = 'email';
  if (channel === 'sms' && !r.Customer_Phone) continue;
  if (channel === 'email' && !r.Customer_Email) continue;
  const first = r.Customer_Name ? String(r.Customer_Name).split(' ')[0] : '';
  const nextAt = new Date(nowMs + interval * 86400000).toISOString();
  out.push({ json: { ...r, _channel: channel, _first: first, _season: season, _month: month, _industry: industry, _segment: r.Segment || '', _last_service: r.Last_Service || '', _next_count: nextCount, _is_last: isLast, _next_touch_at: nextAt } });
  remaining--;
}
return out;

// Parse AI content, enforce guardrails in CODE: length cap, appended business identity + opt-out.
// Safe deterministic fallback so a bad model response never sends broken/empty copy.
const aiRaw = $('Generate Content (AI)').first().json.message?.content ?? $('Generate Content (AI)').first().json;
let p;
try { p = typeof aiRaw === 'string' ? JSON.parse(aiRaw) : aiRaw; } catch (e) { p = null; }
const r = $('Loop Contacts').item.json;
const biz = $env.BUSINESS_NAME || 'us';
const first = r._first ? (' ' + r._first) : '';
const season = (r._season || 'this season');
if (!p || !p.sms) {
  p = {
    topic: season + ' check-in',
    sms: `Hi${first}, a quick hello from ${biz}. As we head into ${String(season).toLowerCase()}, just a reminder we're here if we can help with anything.`,
    email_subject: `${season} check-in from ${biz}`,
    email_body: `Hi${first},\n\nJust a quick hello from ${biz}. As ${String(season).toLowerCase()} approaches, we wanted to stay in touch — if there's anything we can help you with, simply reply or give us a call.\n\nThanks for being a valued customer.`
  };
}
let sms = String(p.sms || '').replace(/\s+/g, ' ').slice(0, 300).trim();
sms = `${sms} Reply STOP to opt out.`;
const emailBody = `${String(p.email_body || '').trim()}\n\n— ${biz}\n\nReply STOP to unsubscribe.`;
return [{ json: { ...r, _topic: p.topic || 'Nurture', _sms_msg: sms, _email_subject: (p.email_subject || `A note from ${biz}`), _email_body: emailBody, _new_status: r._is_last ? 'Nurture Complete' : 'Nurtured' } }];
